inventory = {'Apples': 50, 'Bananas': 30}

def add_item(name, qty):
    if name in inventory:
        inventory[name] += qty
    else:
        inventory[name] = qty

def display_inventory():
    for item, qty in inventory.items():
        print(item, ':', qty)

add_item('Apples', 20)
add_item('Oranges', 40)
display_inventory()
```
